CREATE TABLE IF NOT EXISTS imi_apertura (establecimiento_id INT NOT NULL, producto_id INT NOT NULL, saldo BIGINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(establecimiento_id,producto_id), FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id), FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS imi_reportes (id INT PRIMARY KEY AUTO_INCREMENT, establecimiento_id INT NOT NULL, periodo DATE NOT NULL, estado ENUM('borrador','enviado') NOT NULL DEFAULT 'borrador', version INT NOT NULL DEFAULT 1, actualizado_por INT NULL, actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unico_mes(establecimiento_id,periodo), FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id), FOREIGN KEY(actualizado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS imi_detalles (reporte_id INT NOT NULL, producto_id INT NOT NULL, stock_segun BIGINT UNSIGNED NOT NULL, recibido BIGINT UNSIGNED NOT NULL, consumo BIGINT UNSIGNED NOT NULL, ajuste BIGINT UNSIGNED NOT NULL, stock_inicial BIGINT UNSIGNED NOT NULL, stock_final BIGINT UNSIGNED NOT NULL, PRIMARY KEY(reporte_id,producto_id), FOREIGN KEY(reporte_id) REFERENCES imi_reportes(id) ON DELETE CASCADE, FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
